#!/usr/bin/env node
// Final consolidated UAT E2E: Admin creates Merchant + Partner -> media -> invite/claim -> approve
// -> Partner QR -> Merchant scan -> synthetic transaction -> commission reports.
// Isolated local services only. Email confirmation stays ENABLED; no mail is sent (links are
// generated by Auth admin and followed against local GoTrue; sign-ups are confirmed via local Inbucket).
import { randomUUID } from 'node:crypto';

const url = process.env.VNO_TARGET_URL;
const anonKey = process.env.VNO_TARGET_ANON_KEY;
const serviceKey = process.env.VNO_TARGET_SERVICE_ROLE_KEY;
const backend = process.env.VNO_TEST_BACKEND_URL;
const inbucket = process.env.VNO_TEST_INBUCKET_URL;
if (!url || !anonKey || !serviceKey || !backend || !inbucket) throw new Error('Local target, backend and inbucket variables are required');
if (![url, backend, inbucket].every((v) => ['127.0.0.1', 'localhost', '::1'].includes(new URL(v).hostname))) {
  throw new Error('Final E2E is restricted to isolated local services');
}

const run = randomUUID().slice(0, 8);
const password = 'Local-Rehearsal-Only!42';
const results = [];
const check = (name, pass, evidence = '') => { results.push({ name, status: pass ? 'PASS' : 'FAIL', evidence }); if (!pass) process.exitCode = 1; };
process.on('uncaughtException', (error) => { console.log(JSON.stringify({ status: 'FAIL', fatal: String(error?.cause?.message || error?.message || error), results }, null, 2)); process.exit(1); });
const PNG = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';

async function http(base, route, { key, token, method = 'GET', body, redirect } = {}) {
  const response = await fetch(`${base}${route}`, {
    method, redirect,
    headers: { ...(key ? { apikey: key } : {}), ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body === undefined ? {} : { 'content-type': 'application/json' }) },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await response.text();
  let json; try { json = text ? JSON.parse(text) : null; } catch { json = text; }
  return { status: response.status, json, headers: response.headers };
}
const api = (route, token, o = {}) => http(backend, route, { token, ...o });
const auth = (route, o = {}) => http(url, `/auth/v1${route}`, { key: anonKey, ...o });
const rest = (route, o = {}) => http(url, `/rest/v1${route}`, { key: serviceKey, token: serviceKey, ...o });
const admin = (route, o = {}) => http(url, `/auth/v1/admin${route}`, { key: serviceKey, token: serviceKey, ...o });

async function tokenFromLink(link) {
  const r = await fetch(link, { redirect: 'manual' });
  const loc = r.headers.get('location') || '';
  const frag = new URL(loc, 'http://x').hash.replace(/^#/, '');
  return new URLSearchParams(frag).get('access_token') || (console.error('LINKDBG', r.status, loc.slice(0, 200)), null);
}
async function confirmSignup(email) {
  // Local Mailpit mail capture (no external delivery)
  for (let i = 0; i < 20; i += 1) {
    const list = await http(inbucket, `/api/v1/search?query=${encodeURIComponent(`to:${email}`)}`);
    const id = list.json?.messages?.[0]?.ID;
    if (id) {
      const msg = await http(inbucket, `/api/v1/message/${id}`);
      const link = String(msg.json?.HTML || msg.json?.Text || '').match(/https?:\/\/[^\s"<>)]+verify[^\s"<>)]+/)?.[0]?.replace(/&amp;/g, '&');
      if (link) return link;
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  return null;
}

// ---- bootstrap operator (service-role seeded Admin; equivalent to scripts/create-admin) ----
const adminEmail = `final-admin-${run}@local.invalid`;
const adminUser = (await admin('/users', { method: 'POST', body: { email: adminEmail, password, email_confirm: true } })).json;
await rest('/user_profiles', { method: 'POST', body: { user_id: adminUser.id, email: adminEmail, role: 'admin', user_profiles_status: 'active', login_count: 0 } });
const adminLogin = await api('/auth/login', undefined, { method: 'POST', body: { email: adminEmail, password, userType: 'admin' } });
const A = adminLogin.json?.access_token;
check('Admin logs in', !!A, `HTTP ${adminLogin.status}`);

// ---- 1. Admin creates Merchant + Partner ----
const mEmail = `final-merchant-${run}@local.invalid`;
const pEmail = `final-partner-${run}@local.invalid`;
const m = await api('/merchants/admin', A, { method: 'POST', body: {
  owner_email: mEmail, merchant_name: `Final Merchant ${run}`, merchant_phone: '0900000001', merchant_email: mEmail, owner_name: 'Final Owner',
  merchant_commission_type: 'percentage', merchant_commission_value: '0.1000', merchant_discount_type: 'percentage', merchant_discount_value: '0.0500' } });
const merchantId = m.json?.merchant_system_id;
check('Admin creates Merchant', m.status === 201 && !!merchantId, `HTTP ${m.status}`);
const p = await api('/collaborators/admin', A, { method: 'POST', body: {
  collaborators_name: `Final Partner ${run}`, collaborators_phone: '0900000002', collaborators_email: pEmail, merchant_system_id: merchantId } });
const partnerId = p.json?.id;
const partnerCode = p.json?.collaborators_code;
check('Admin creates Partner assigned to Merchant', p.status === 201 && !!partnerId && !!partnerCode, `HTTP ${p.status}`);

// ---- 2. Admin uploads images (direct publish) ----
for (const [label, body] of [['Merchant', { merchant_id: merchantId }], ['Partner', { collaborator_id: partnerId }]]) {
  const up = await api('/media/upload', A, { method: 'POST', body: { filename: 'a.png', mime_type: 'image/png', size_bytes: Buffer.from(PNG, 'base64').length, base64_data: PNG, slot: 'main', direct_publish: true, ...body } });
  check(`Admin uploads ${label} image (direct publish)`, up.status === 201 || up.status === 200, `HTTP ${up.status} ${up.status >= 300 ? JSON.stringify(up.json) : ''}`);
}

// ---- 3. Invitations: authorization ----
const mInv = await api('/invitations', A, { method: 'POST', body: { entity_type: 'merchant', entity_id: merchantId } });
const pInv = await api('/invitations', A, { method: 'POST', body: { entity_type: 'collaborator', entity_id: partnerId } });
check('Admin creates Merchant + Partner invitations', mInv.status === 201 && pInv.status === 201 && !!mInv.json?.invite_link && !!pInv.json?.invite_link, `HTTP ${mInv.status}/${pInv.status}`);
check('Invitation expires within 7 days', (new Date(mInv.json?.expires_at) - Date.now()) <= 7 * 864e5 + 6e4, mInv.json?.expires_at);
const dup = await api('/invitations', A, { method: 'POST', body: { entity_type: 'merchant', entity_id: merchantId } });
check('Second pending invitation for same entity is rejected', dup.status === 400, `HTTP ${dup.status}`);
const noAuth = await api('/invitations', undefined, { method: 'POST', body: { entity_type: 'merchant', entity_id: merchantId } });
check('Unauthenticated invitation create denied', noAuth.status === 401, `HTTP ${noAuth.status}`);

// attacker: verified Auth user (real sign-up + local-mail confirmation), different email
const atkEmail = `final-attacker-${run}@local.invalid`;
const su = await auth('/signup', { method: 'POST', body: { email: atkEmail, password } });
check('Sign-up with confirmation enabled returns no session', su.status === 200 && !su.json?.access_token, `HTTP ${su.status}`);
const unconfirmedLogin = await auth('/token?grant_type=password', { method: 'POST', body: { email: atkEmail, password } });
check('Unconfirmed identity cannot obtain a session', unconfirmedLogin.status >= 400, `HTTP ${unconfirmedLogin.status}`);
const atkLink = await confirmSignup(atkEmail);
await fetch(atkLink, { redirect: 'manual' });
const atkSession = await auth('/token?grant_type=password', { method: 'POST', body: { email: atkEmail, password } });
const ATK = atkSession.json?.access_token;
check('Attacker confirms own email via mail capture', !!ATK, `HTTP ${atkSession.status}`);
for (const [label, type, id, inv] of [['Merchant', 'merchant', merchantId, mInv], ['Partner', 'collaborator', partnerId, pInv]]) {
  const r = await api(`/invitations/claim/${type}/${id}?invitation=${inv.json.id}`, ATK, { method: 'POST' });
  check(`Verified non-owner cannot claim ${label}`, r.status === 403, `HTTP ${r.status}`);
}
const nonAdminCreate = await api('/invitations', ATK, { method: 'POST', body: { entity_type: 'merchant', entity_id: merchantId } });
const nonAdminRevoke = await api(`/invitations/${mInv.json.id}`, ATK, { method: 'DELETE' });
const nonAdminRead = await api(`/invitations/for/merchant/${merchantId}`, ATK);
check('Non-admin cannot create/read/revoke invitations', [nonAdminCreate, nonAdminRevoke, nonAdminRead].every((r) => r.status === 403), `${nonAdminCreate.status}/${nonAdminRevoke.status}/${nonAdminRead.status}`);
const badId = await api('/invitations/claim/merchant/not-a-uuid', ATK, { method: 'POST' });
const badType = await api(`/invitations/claim/admin/${merchantId}`, ATK, { method: 'POST' });
check('Malformed entity id / type rejected with 400', badId.status === 400 && badType.status === 400, `${badId.status}/${badType.status}`);
const rowStillPending = (await rest(`/invitations?id=eq.${mInv.json.id}&select=status`)).json?.[0]?.status;
check('Failed claims leave invitation pending', rowStillPending === 'pending', rowStillPending);

// anon / authenticated roles cannot read invite links straight from PostgREST
const anonRead = await http(url, '/rest/v1/invitations?select=invite_link', { key: anonKey });
const userRead = await http(url, '/rest/v1/invitations?select=invite_link', { key: anonKey, token: ATK });
check('anon/authenticated cannot read invitations via PostgREST', [anonRead, userRead].every((r) => r.status === 401 || r.status === 403 || (Array.isArray(r.json) && r.json.length === 0)), `${anonRead.status}/${userRead.status}`);

// ---- 4. Owners claim with Auth-issued, email-verified sessions ----
const mTok = await tokenFromLink(mInv.json.invite_link);
const pTok = await tokenFromLink(pInv.json.invite_link);
check('Invite links yield Auth sessions', !!mTok && !!pTok);
const mUser = (await auth('/user', { token: mTok })).json;
check('Invite session has confirmed email matching target', !!mUser?.email_confirmed_at && mUser.email === mEmail, mUser?.email);

const wrongTypeClaim = await api(`/invitations/claim/collaborator/${partnerId}?invitation=${mInv.json.id}`, mTok, { method: 'POST' });
check('Merchant owner cannot use Merchant invitation on Partner entity', wrongTypeClaim.status === 403, `HTTP ${wrongTypeClaim.status}`);
const crossClaim = await api(`/invitations/claim/collaborator/${partnerId}?invitation=${pInv.json.id}`, mTok, { method: 'POST' });
check('Merchant owner cannot claim Partner record', crossClaim.status === 403, `HTTP ${crossClaim.status}`);

const [c1, c2] = await Promise.all([
  api(`/invitations/claim/merchant/${merchantId}?invitation=${mInv.json.id}`, mTok, { method: 'POST' }),
  api(`/invitations/claim/merchant/${merchantId}?invitation=${mInv.json.id}`, mTok, { method: 'POST' }),
]);
check('Concurrent double-claim: exactly one succeeds', [c1, c2].filter((r) => r.status === 201).length === 1, `${c1.status}/${c2.status}`);
const profiles = (await rest(`/user_profiles?merchant_id=eq.${merchantId}&select=role,user_profiles_status,user_id`)).json;
check('Exactly one pending Merchant profile bound to verified Auth user', profiles.length === 1 && profiles[0].user_profiles_status === 'pending' && profiles[0].user_id === mUser.id, JSON.stringify(profiles));
const replay = await api(`/invitations/claim/merchant/${merchantId}?invitation=${mInv.json.id}`, mTok, { method: 'POST' });
check('Claim replay rejected', replay.status === 400, `HTTP ${replay.status}`);
const revokeAccepted = await api(`/invitations/${mInv.json.id}`, A, { method: 'DELETE' });
check('Accepted invitation cannot be revoked', revokeAccepted.status === 400, `HTTP ${revokeAccepted.status}`);
const pendingLogin = await api('/auth/login', undefined, { method: 'POST', body: { email: mEmail, password, userType: 'merchant' } });
check('Claimed-but-unapproved Merchant cannot access the system', pendingLogin.status === 401, `HTTP ${pendingLogin.status}`);

const pClaim = await api(`/invitations/claim/collaborator/${partnerId}?invitation=${pInv.json.id}`, pTok, { method: 'POST' });
check('Partner owner claims Partner record', pClaim.status === 201 && pClaim.json?.role === 'collaborator', `HTTP ${pClaim.status}`);

// ---- 5. Revoke / expiry / re-invite on a third record ----
const r3 = await api('/merchants/admin', A, { method: 'POST', body: { owner_email: `final-m3-${run}@local.invalid`, merchant_name: `Final M3 ${run}`, merchant_phone: '0900000003', merchant_email: `final-m3-${run}@local.invalid` } });
const m3 = r3.json?.merchant_system_id;
const i3 = await api('/invitations', A, { method: 'POST', body: { entity_type: 'merchant', entity_id: m3 } });
const t3 = await tokenFromLink(i3.json?.invite_link);
const rev = await api(`/invitations/${i3.json.id}`, A, { method: 'DELETE' });
const revClaim = await api(`/invitations/claim/merchant/${m3}?invitation=${i3.json.id}`, t3, { method: 'POST' });
check('Revoked invitation cannot be claimed', rev.status === 200 && revClaim.status === 400, `${rev.status}/${revClaim.status}`);
const i3b = await api('/invitations', A, { method: 'POST', body: { entity_type: 'merchant', entity_id: m3 } });
check('Re-invite after revoke works', i3b.status === 201, `HTTP ${i3b.status}`);
await rest(`/invitations?id=eq.${i3b.json.id}`, { method: 'PATCH', body: { expires_at: new Date(Date.now() - 1000).toISOString() } });
const t3b = await tokenFromLink(i3b.json.invite_link);
const expClaim = await api(`/invitations/claim/merchant/${m3}?invitation=${i3b.json.id}`, t3b, { method: 'POST' });
check('Expired invitation cannot be claimed', expClaim.status === 400 && /expired/i.test(JSON.stringify(expClaim.json)), `HTTP ${expClaim.status}`);
const i3c = await api('/invitations', A, { method: 'POST', body: { entity_type: 'merchant', entity_id: m3 } });
check('Re-invite after expiry works (stale pending cleared)', i3c.status === 201, `HTTP ${i3c.status}`);

// existing-profile protection: an Admin cannot be rebound by a claim for their own email
const m4Email = adminEmail;
const r4 = await api('/merchants/admin', A, { method: 'POST', body: { owner_email: m4Email, merchant_name: `Final M4 ${run}`, merchant_phone: '0900000004', merchant_email: m4Email } });
const i4 = await api('/invitations', A, { method: 'POST', body: { entity_type: 'merchant', entity_id: r4.json?.merchant_system_id } });
const adminClaim = await api(`/invitations/claim/merchant/${r4.json?.merchant_system_id}?invitation=${i4.json?.id}`, A, { method: 'POST' });
const adminRole = (await rest(`/user_profiles?user_id=eq.${adminUser.id}&select=role`)).json?.[0]?.role;
check('Claim cannot overwrite an existing Admin profile', adminClaim.status === 400 && adminRole === 'admin', `HTTP ${adminClaim.status}; role ${adminRole}`);

// ---- 6. Admin approves ----
const aM = await api(`/merchants/${merchantId}/approve`, A, { method: 'POST' });
const aP = await api(`/collaborators/${partnerId}/approve`, A, { method: 'POST' });
check('Admin approves claimed Merchant + Partner', aM.status === 201 && aP.status === 201, `HTTP ${aM.status}/${aP.status} ${aM.status >= 300 ? JSON.stringify(aM.json) : ''}`);
const unclaimed = await api(`/collaborators/${(await api('/collaborators/admin', A, { method: 'POST', body: { collaborators_name: 'Unclaimed', collaborators_phone: '0900000009', collaborators_email: `final-unclaimed-${run}@local.invalid` } })).json?.id}/approve`, A, { method: 'POST' });
check('Admin cannot approve an unclaimed (identity-less) Partner', unclaimed.status >= 400, `HTTP ${unclaimed.status}`);

// owners set their own password through their verified session, then log in
for (const tok of [mTok, pTok]) await auth('/user', { token: tok, method: 'PUT', body: { password } });
const ML = (await api('/auth/login', undefined, { method: 'POST', body: { email: mEmail, password, userType: 'merchant' } })).json?.access_token;
const PL = (await api('/auth/login', undefined, { method: 'POST', body: { email: pEmail, password, userType: 'collaborator' } })).json?.access_token;
check('Approved owners can log in', !!ML && !!PL);

// ---- 7. Partner QR -> Merchant scan -> synthetic transaction -> reports ----
const qr = await api('/collaborators/me/qr-code', PL);
check('Partner QR available after approval', qr.status === 200 && !!(qr.json?.collaborators_qr_code || qr.json?.qr_code || qr.json), `HTTP ${qr.status}`);
const code = qr.json?.collaborators_code || partnerCode;
const scan = await api('/qr/resolve', ML, { method: 'POST', body: { payload: code } });
check('Merchant scans Partner QR', scan.status === 201 && scan.json?.association === 'assigned_to_this_merchant', `HTTP ${scan.status}; ${scan.json?.association}`);
const key = randomUUID();
const tx = await api('/transactions/simulation', ML, { method: 'POST', body: { collaborator_code: code, gross_amount: '1234.5678', idempotency_key: key } });
check('Synthetic transaction created', tx.status === 201 && tx.json?.record_kind === 'uat_simulation' && tx.json?.external_settlement_enabled === false, `HTTP ${tx.status} ${tx.status >= 300 ? JSON.stringify(tx.json) : ''}`);
check('Discount/commission exact at four decimals', String(tx.json?.discount_amount) === '61.7284' && String(tx.json?.commission_amount) === '123.4568', `${tx.json?.discount_amount}/${tx.json?.commission_amount}`);
for (const [role, token, route] of [['Admin', A, '/transactions/report'], ['Merchant', ML, '/transactions/me/report'], ['Partner', PL, '/transactions/me/report']]) {
  const rep = await api(`${route}?record_kind=uat_simulation&page=1&page_size=10`, token);
  check(`${role} commission report shows the transaction`, rep.status === 200 && rep.json?.items?.some((i) => i.id === tx.json?.transaction_id), `HTTP ${rep.status}; rows ${rep.json?.summary?.transaction_count}`);
}
const notPartnerTx = await api('/transactions/simulation', PL, { method: 'POST', body: { collaborator_code: code, gross_amount: '1.0000', idempotency_key: randomUUID() } });
check('Partner cannot create Merchant simulation', notPartnerTx.status === 403, `HTTP ${notPartnerTx.status}`);

// audit trail
const audits = (await rest(`/audit_events?select=action&action=like.invitation.%25`)).json;
check('Invitation lifecycle audited', Array.isArray(audits) && ['invitation.created', 'invitation.accepted', 'invitation.revoked'].every((a) => audits.some((x) => x.action === a)), JSON.stringify([...new Set((Array.isArray(audits) ? audits : []).map((a) => a.action))]));

console.log(JSON.stringify({ status: results.every((r) => r.status === 'PASS') ? 'PASS' : 'FAIL', run, controls: results.length, passed: results.filter((r) => r.status === 'PASS').length, results }, null, 2));
